    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.deepEqual(result.value, {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 2,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  });
});

